python3 -c 'import hashlib, os, pathlib, subprocess; files=["prompts-assembled/LEAD.xml","prompts/LEAD.xml","prompts-assembled/SYSTEMS.xml","prompts/SYSTEMS.xml","prompts-assembled/WEB.xml","prompts/WEB.xml","prompts-assembled/ANDROID.xml","prompts/ANDROID.xml","prompts-assembled/IOS.xml","prompts/IOS.xml","prompts-assembled/INFRA.xml","prompts/INFRA.xml","prompts-assembled/QUALITY.xml","prompts/QUALITY.xml"];
def digests():
    return {f: hashlib.sha256(pathlib.Path(f).read_bytes()).hexdigest() for f in files}
before=digests(); env=os.environ.copy(); env["DEFAULT_BRANCH"]="main"; r=subprocess.run(["bash","scripts/assemble-prompts.sh"], env=env, capture_output=True, text=True); after=digests(); changed=[f for f in files if before[f]!=after[f]]; print({"assemble_exit": r.returncode, "changed": changed}); raise SystemExit(0 if r.returncode==0 and not changed else 1)'
